/* ==========================================================================
   英単語3Dフラッシュカード - デザインシステム & アニメーション
   ========================================================================== */

:root {
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: #e0e7ff;
  --primary-glow: rgba(79, 70, 229, 0.25);
  --success: #10b981;
  --success-hover: #059669;
  --success-bg: #ecfdf5;
  --warning: #f59e0b;
  --warning-hover: #d97706;
  --warning-bg: #fffbeb;
  --danger: #ef4444;
  --danger-hover: #dc2626;
  --surface: #ffffff;
  --surface-alt: #f8fafc;
  --bg-gradient-start: #f1f5f9;
  --bg-gradient-end: #e2e8f0;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-subtle: #94a3b8;
  --border-light: #e2e8f0;
  --border-focus: #818cf8;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
  --shadow-card: 0 20px 35px -10px rgba(15, 23, 42, 0.12), 0 8px 16px -4px rgba(15, 23, 42, 0.06);
  --shadow-card-hover: 0 25px 45px -10px rgba(79, 70, 229, 0.18), 0 12px 20px -6px rgba(15, 23, 42, 0.08);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Yu Gothic", sans-serif;
  --transition-smooth: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: linear-gradient(145deg, #f8fafc 0%, #eef2ff 50%, #f1f5f9 100%);
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ==========================================================================
   コンテナ・レイアウト
   ========================================================================== */

.app-container {
  max-width: 720px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  min-height: 100vh;
}

.app-header {
  text-align: center;
  position: relative;
}

.header-title {
  font-size: 1.85rem;
  font-weight: 800;
  background: linear-gradient(135deg, #3730a3 0%, #4f46e5 50%, #7c3aed 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -0.025em;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 4px;
}

/* ==========================================================================
   統計バー・進捗バー
   ========================================================================== */

.stats-bar {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  background: var(--surface);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-light);
  gap: 8px;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.stat-value {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.2;
}

.stat-value-mastered {
  color: var(--success);
}

.stat-value-learning {
  color: var(--warning);
}

.stat-value-total {
  color: var(--primary);
}

.stat-label {
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--text-muted);
  margin-top: 2px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.progress-container {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 4px;
}

.progress-bar {
  width: 100%;
  height: 8px;
  background-color: #e2e8f0;
  border-radius: var(--radius-full);
  overflow: hidden;
  position: relative;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #4f46e5, #10b981);
  border-radius: var(--radius-full);
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ==========================================================================
   フィルターセクション（カテゴリタブ / 習得ステータス）
   ========================================================================== */

.filter-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(8px);
  padding: 12px 14px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-light);
}

.category-tabs,
.status-filters {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 2px;
  scrollbar-width: none;
}

.category-tabs::-webkit-scrollbar,
.status-filters::-webkit-scrollbar {
  display: none;
}

.tab-btn,
.status-btn {
  border: 1px solid var(--border-light);
  background: var(--surface);
  color: var(--text-muted);
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: var(--transition-smooth);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.tab-btn:hover,
.status-btn:hover {
  background: #f1f5f9;
  color: var(--text-main);
  border-color: #cbd5e1;
}

.tab-btn-active,
.status-btn-active {
  background: var(--primary) !important;
  color: #ffffff !important;
  border-color: var(--primary) !important;
  box-shadow: 0 2px 8px var(--primary-glow);
}

/* ==========================================================================
   3Dカード反転ステージ
   ========================================================================== */

.card-stage {
  perspective: 1200px;
  -webkit-perspective: 1200px;
  width: 100%;
  margin: 8px auto;
  display: flex;
  justify-content: center;
}

.flip-card {
  width: 100%;
  max-width: 480px;
  min-height: 330px;
  background: transparent;
  cursor: pointer;
  user-select: none;
}

.flip-card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 330px;
  text-align: center;
  transition: transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  -webkit-transform-style: preserve-3d;
  transform-style: preserve-3d;
}

.flip-card-flipped {
  -webkit-transform: rotateY(180deg);
  transform: rotateY(180deg);
}

.card-face {
  position: absolute;
  width: 100%;
  height: 100%;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  -webkit-transform: translateZ(0);
  transform: translateZ(0);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-card);
  border: 1px solid rgba(255, 255, 255, 0.8);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-sizing: border-box;
}

.card-stage:hover .flip-card-inner {
  box-shadow: var(--shadow-card-hover);
}

/* 表面デザイン */
.card-front {
  background: linear-gradient(135deg, #ffffff 0%, #fbfcfe 100%);
  color: var(--text-main);
}

/* 裏面デザイン */
.card-back {
  background: linear-gradient(135deg, #eef2ff 0%, #e0e7ff 100%);
  color: #1e1b4b;
  -webkit-transform: rotateY(180deg) translateZ(0);
  transform: rotateY(180deg) translateZ(0);
  border-color: #c7d2fe;
}

/* カードヘッダー部 */
.card-badge {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
}

.card-category-tag {
  background: rgba(79, 70, 229, 0.1);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  letter-spacing: 0.05em;
}

.card-number-tag {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-weight: 600;
}

/* カード文字タイポグラフィ */
.card-word {
  font-size: 2.3rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-main);
  margin-top: 16px;
  line-height: 1.2;
}

.card-phonetic {
  font-size: 1.1rem;
  color: var(--primary);
  font-weight: 500;
  font-family: "Lucida Sans Unicode", "DejaVu Sans", sans-serif;
  margin-top: 4px;
}

.card-meaning {
  font-size: 1.8rem;
  font-weight: 700;
  color: #1e1b4b;
  margin-top: 8px;
  line-height: 1.3;
}

.card-part-of-speech {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  color: #6366f1;
  background: rgba(99, 102, 241, 0.15);
  padding: 2px 8px;
  border-radius: 4px;
  margin-bottom: 6px;
}

/* 例文ボックス */
.card-example-box {
  background: rgba(255, 255, 255, 0.85);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  border: 1px solid rgba(199, 210, 254, 0.6);
  text-align: left;
  margin-top: 12px;
}

.example-en {
  font-size: 0.95rem;
  font-weight: 600;
  color: #312e81;
  line-height: 1.4;
}

.example-ja {
  font-size: 0.85rem;
  color: #475569;
  margin-top: 4px;
  line-height: 1.4;
}

/* 音声ボタンと反転ヒント */
.sound-btn {
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  color: var(--primary);
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition-smooth);
  margin-top: 12px;
  box-shadow: var(--shadow-sm);
}

.sound-btn:hover {
  background: var(--primary);
  color: #ffffff;
  transform: scale(1.08);
}

.flip-hint {
  font-size: 0.78rem;
  color: var(--text-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

/* ==========================================================================
   アクションツールバー & 各種ボタン
   ========================================================================== */

.action-toolbar {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.control-group {
  display: flex;
  gap: 10px;
  width: 100%;
}

.control-group-utility {
  justify-content: center;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 4px;
}

.btn-nav,
.btn-mastered,
.btn-learning,
.btn-shuffle,
.btn-reset,
.add-card-toggle,
.btn-submit,
.btn-cancel {
  border: none;
  outline: none;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: var(--radius-md);
  transition: var(--transition-smooth);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 18px;
}

.btn-nav {
  background: var(--surface);
  color: var(--text-main);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-sm);
  flex: 1;
}

.btn-nav:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #cbd5e1;
  transform: translateY(-1px);
}

.btn-nav:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn-mastered {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
  flex: 1;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.25);
}

.btn-mastered:hover {
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(16, 185, 129, 0.35);
}

.btn-learning {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  color: #ffffff;
  flex: 1;
  box-shadow: 0 4px 12px rgba(245, 158, 11, 0.25);
}

.btn-learning:hover {
  background: linear-gradient(135deg, #d97706 0%, #b45309 100%);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(245, 158, 11, 0.35);
}

.btn-shuffle {
  background: var(--surface);
  color: var(--text-muted);
  border: 1px solid var(--border-light);
  padding: 8px 14px;
  font-size: 0.85rem;
}

.btn-shuffle:hover {
  background: #f1f5f9;
  color: var(--text-main);
}

.btn-reset {
  background: #f1f5f9;
  color: var(--text-muted);
  padding: 8px 16px;
  font-size: 0.85rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-light);
}

.btn-reset:hover {
  background: #e2e8f0;
  color: var(--text-main);
}

.add-card-toggle {
  background: linear-gradient(135deg, #4f46e5 0%, #4338ca 100%);
  color: #ffffff;
  box-shadow: 0 4px 12px var(--primary-glow);
  padding: 10px 16px;
  border-radius: var(--radius-full);
  font-size: 0.9rem;
}

.add-card-toggle:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(79, 70, 229, 0.35);
}

/* ==========================================================================
   モーダルダイアログ & 単語追加フォーム
   ========================================================================== */

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 1000;
  animation: fadeIn 0.2s ease-out;
}

.modal-content {
  background: var(--surface);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 480px;
  padding: 24px;
  box-shadow: var(--shadow-lg);
  max-height: 90vh;
  overflow-y: auto;
  border: 1px solid var(--border-light);
  animation: modalSlideUp 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.modal-title {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
  text-align: left;
}

.form-group label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
}

.form-input,
.form-textarea {
  width: 100%;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  font-family: inherit;
  font-size: 0.95rem;
  color: var(--text-main);
  background: #f8fafc;
  transition: var(--transition-smooth);
}

.form-input:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--border-focus);
  background: #ffffff;
  box-shadow: 0 0 0 3px var(--primary-glow);
}

.form-textarea {
  resize: vertical;
  min-height: 64px;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
}

.btn-submit {
  background: var(--primary);
  color: #ffffff;
  padding: 10px 20px;
}

.btn-submit:hover {
  background: var(--primary-hover);
}

.btn-cancel {
  background: #f1f5f9;
  color: var(--text-muted);
  padding: 10px 18px;
}

.btn-cancel:hover {
  background: #e2e8f0;
  color: var(--text-main);
}

/* ==========================================================================
   空ステート (条件一致カードなし)
   ========================================================================== */

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 16px;
  text-align: center;
  background: var(--surface);
  border-radius: var(--radius-lg);
  border: 2px dashed var(--border-light);
  gap: 14px;
  color: var(--text-muted);
}

/* ==========================================================================
   アニメーションキーフレーム
   ========================================================================== */

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes modalSlideUp {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ==========================================================================
   レスポンシブ対応
   ========================================================================== */

@media (max-width: 480px) {
  .app-container {
    padding: 16px 12px 32px;
    gap: 16px;
  }

  .header-title {
    font-size: 1.5rem;
  }

  .stat-value {
    font-size: 1.15rem;
  }

  .stat-label {
    font-size: 0.65rem;
  }

  .flip-card,
  .flip-card-inner {
    min-height: 290px;
  }

  .card-face {
    padding: 18px;
  }

  .card-word {
    font-size: 1.85rem;
  }

  .card-meaning {
    font-size: 1.45rem;
  }

  .btn-nav,
  .btn-mastered,
  .btn-learning {
    padding: 10px 14px;
    font-size: 0.88rem;
  }
}

export type CardCategory = 'daily' | 'business' | 'academic' | 'travel';

export type FilterCategory = 'all' | CardCategory;

export type CardStatusFilter = 'all' | 'learning' | 'mastered';

export interface FlashCard {
  id: string;
  word: string;
  phonetic: string;
  partOfSpeech: string;
  meaning: string;
  exampleEn: string;
  exampleJa: string;
  category: CardCategory;
  isMastered: boolean;
}

export type CardFormData = Omit<FlashCard, 'id' | 'isMastered'>;

export interface CategoryOption {
  readonly id: CardCategory;
  readonly label: string;
}

import { useState, MouseEvent, KeyboardEvent } from 'react';
import { Volume2, RotateCcw, AlertTriangle } from 'lucide-react';
import { FlashCard } from '../types';
import { CATEGORY_LABELS } from '../sampleData';

interface FlashCardItemProps {
  card: FlashCard;
  isFlipped: boolean;
  onFlip: () => void;
  currentIndex: number;
  totalCards: number;
}

const FlashCardItem = ({
  card,
  isFlipped,
  onFlip,
  currentIndex,
  totalCards,
}: FlashCardItemProps) => {
  const [isSpeaking, setIsSpeaking] = useState<boolean>(false);
  const [speechError, setSpeechError] = useState<string | null>(null);

  const handleSpeech = (e: MouseEvent<HTMLButtonElement> | KeyboardEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    setSpeechError(null);

    if (!('speechSynthesis' in window)) {
      const msg = 'お使いのブラウザは音声読み上げ機能（Web Speech API）に対応していません。';
      setSpeechError(msg);
      window.alert(msg);
      return;
    }

    try {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(card.word);
      utterance.lang = 'en-US';
      utterance.rate = 0.85;

      utterance.onstart = () => {
        setIsSpeaking(true);
      };

      utterance.onend = () => {
        setIsSpeaking(false);
      };

      utterance.onerror = () => {
        setIsSpeaking(false);
        setSpeechError('音声の再生中にエラーが発生しました。');
      };

      window.speechSynthesis.speak(utterance);
    } catch {
      setIsSpeaking(false);
      setSpeechError('音声の再生に失敗しました。');
    }
  };

  const categoryLabel = CATEGORY_LABELS[card.category] ?? card.category;

  return (
    <div className="card-stage">
      <div
        className="flip-card"
        onClick={onFlip}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onFlip?.();
          }
        }}
        aria-label={`単語カード: ${card.word}。クリックまたはスペースキーで裏返します`}
      >
        <div className={isFlipped ? 'flip-card-inner flip-card-flipped' : 'flip-card-inner'}>
          {/* カード表面 */}
          <div className="card-face card-front">
            <div className="card-badge">
              <span className="card-category-tag">{categoryLabel}</span>
              <span className="card-number-tag">
                {currentIndex + 1} / {totalCards}
              </span>
            </div>

            <div>
              <h2 className="card-word">{card.word}</h2>
              <div className="card-phonetic">{card.phonetic}</div>
              <button
                type="button"
                className="sound-btn"
                onClick={handleSpeech}
                onKeyDown={(e) => {
                  e.stopPropagation();
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleSpeech(e);
                  }
                }}
                disabled={isSpeaking}
                title={speechError || (isSpeaking ? '発音再生中...' : '発音を再生する')}
                aria-label={`${card.word} の音声発音を聴く`}
              >
                {speechError ? <AlertTriangle size={20} color="#ef4444" /> : <Volume2 size={22} />}
              </button>
            </div>

            <div className="flip-hint">
              <RotateCcw size={14} />
              <span>タップして日本語訳を表示</span>
            </div>
          </div>

          {/* カード裏面 */}
          <div className="card-face card-back">
            <div className="card-badge">
              <span className="card-category-tag">{categoryLabel}</span>
              <span className="card-number-tag">
                {currentIndex + 1} / {totalCards}
              </span>
            </div>

            <div>
              <span className="card-part-of-speech">{card.partOfSpeech}</span>
              <h3 className="card-meaning">{card.meaning}</h3>

              <div className="card-example-box">
                <p className="example-en">{card.exampleEn}</p>
                <p className="example-ja">{card.exampleJa}</p>
              </div>
            </div>

            <div className="flip-hint">
              <RotateCcw size={14} />
              <span>タップして英単語へ戻る</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FlashCardItem;

