  onNext: () => void;
  onMarkMastered: () => void;
  onMarkLearning: () => void;
  onShuffle: () => void;
  onOpenAddModal: () => void;
  canPrev: boolean;
  canNext: boolean;
  isMastered: boolean;
}

const CardControls = ({
  onPrev,
  onNext,
  onMarkMastered,
  onMarkLearning,
  onShuffle,
  onOpenAddModal,
  canPrev,
  canNext,
  isMastered,
