export default CardControls;

import { useState, useMemo, useEffect, useCallback, ChangeEvent, FormEvent } from 'react';
import { BookOpen, Sparkles, Plus, AlertCircle, RefreshCw } from 'lucide-react';
import { FlashCard, FilterCategory, CardStatusFilter, CardFormData } from './types';
import { initialCards, CATEGORY_OPTIONS } from './sampleData';
import FlashCardItem from './components/FlashCardItem';
import CardControls from './components/CardControls';

const initialFormState: CardFormData = {
  word: '',
  phonetic: '',
  partOfSpeech: '名詞',
  meaning: '',
  exampleEn: '',
  exampleJa: '',
  category: 'daily',
};

const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `card-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
};

const App = () => {
  const [cards, setCards] = useState<FlashCard[]>(() => {
    try {
      const saved = localStorage.getItem('flashcards_data');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return parsed;
        }
      }
    } catch {
      // 読み込みエラー時は初期データを使用
    }
    return initialCards;
  });

  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [isFlipped, setIsFlipped] = useState<boolean>(false);
  const [selectedCategory, setSelectedCategory] = useState<FilterCategory>('all');
  const [statusFilter, setStatusFilter] = useState<CardStatusFilter>('all');
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);

  // 新規単語登録用フォームステート
  const [formData, setFormData] = useState<CardFormData>(initialFormState);

  // ローカルストレージ自動保存
  useEffect(() => {
    try {
      localStorage.setItem('flashcards_data', JSON.stringify(cards));
    } catch {
      // 保存不可時のフォールバック
    }
  }, [cards]);

  // フィルタリング処理
  const filteredCards = useMemo(() => {
    return cards.filter((card) => {
      const categoryMatch = selectedCategory === 'all' || card.category === selectedCategory;
      const statusMatch =
        statusFilter === 'all' ||
        (statusFilter === 'mastered' && card.isMastered) ||
        (statusFilter === 'learning' && !card.isMastered);
      return categoryMatch && statusMatch;
    });
  }, [cards, selectedCategory, statusFilter]);

  // フィルタ切り替え時にインデックス範囲を安全に補正
  useEffect(() => {
    setCurrentIndex(0);
    setIsFlipped(false);
  }, [selectedCategory, statusFilter]);

  // フィルタ後の要素数が変化した際の安全なインデックスガード
  useEffect(() => {
    if (filteredCards.length > 0 && currentIndex >= filteredCards.length) {
      setCurrentIndex(filteredCards.length - 1);
    }
  }, [filteredCards.length, currentIndex]);

  // 統計情報計算
  const totalCount = cards.length;
  const masteredCount = useMemo(() => cards.filter((c) => c.isMastered).length, [cards]);
  const learningCount = totalCount - masteredCount;
  const masterPercentage = totalCount > 0 ? Math.round((masteredCount / totalCount) * 100) : 0;

  // 現在のカード
  const currentCard = filteredCards[currentIndex];

  const handleFlip = useCallback(() => {
    setIsFlipped((prev) => !prev);
  }, []);

  const handlePrev = useCallback(() => {
    if (currentIndex > 0) {
      setIsFlipped(false);
      setCurrentIndex((prev) => prev - 1);
    }
  }, [currentIndex]);

  const handleNext = useCallback(() => {
    if (currentIndex < filteredCards.length - 1) {
      setIsFlipped(false);
      setCurrentIndex((prev) => prev + 1);
    }
  }, [currentIndex, filteredCards.length]);

  const updateCardMasteredStatus = useCallback(
    (isMastered: boolean) => {
      if (!currentCard) return;

      setIsFlipped(false);

      const willBeRemovedFromFilter =
        (statusFilter === 'learning' && isMastered) ||
        (statusFilter === 'mastered' && !isMastered);

      if (willBeRemovedFromFilter) {
        if (currentIndex >= filteredCards.length - 1) {
          setCurrentIndex((prev) => Math.max(0, prev - 1));
        }
      } else {
        if (currentIndex < filteredCards.length - 1) {
          setCurrentIndex((prev) => prev + 1);
        }
      }

      setCards((prev) =>
        prev.map((c) => (c.id === currentCard.id ? { ...c, isMastered } : c))
      );
    },
    [currentCard, currentIndex, filteredCards.length, statusFilter]
  );

  const handleMarkMastered = useCallback(() => {
    updateCardMasteredStatus(true);
  }, [updateCardMasteredStatus]);

  const handleMarkLearning = useCallback(() => {
    updateCardMasteredStatus(false);
  }, [updateCardMasteredStatus]);

  const handleShuffle = useCallback(() => {
    setIsFlipped(false);
    setCurrentIndex(0);
    setCards((prev) => {
      const copy = [...prev];
      for (let i = copy.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [copy[i], copy[j]] = [copy[j], copy[i]];
      }
      return copy;
    });
  }, []);

  const handleResetFilters = () => {
    setSelectedCategory('all');
    setStatusFilter('all');
  };

  // キーボードショートカット (左右キーで移動、Spaceキーで反転)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isModalOpen) return;

      if (e.code === 'Space') {
        e.preventDefault();
        handleFlip();
      } else if (e.code === 'ArrowLeft') {
        e.preventDefault();
        handlePrev();
      } else if (e.code === 'ArrowRight') {
        e.preventDefault();
        handleNext();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleFlip, handlePrev, handleNext, isModalOpen]);

  const handleFormChange = (
    e: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  // 新規単語追加送信
  const handleAddCardSubmit = (e: FormEvent) => {
    e.preventDefault();
    const trimmedWord = formData.word.trim();
    const trimmedMeaning = formData.meaning.trim();
    if (!trimmedWord || !trimmedMeaning) return;

    const newCardItem: FlashCard = {
      id: generateId(),
      word: trimmedWord,
      phonetic: formData.phonetic.trim() || `/${trimmedWord.toLowerCase()}/`,
      partOfSpeech: formData.partOfSpeech,
      meaning: trimmedMeaning,
      exampleEn: formData.exampleEn.trim() || `I practice using "${trimmedWord}" every day.`,
      exampleJa: formData.exampleJa.trim() || `私は「${trimmedWord}」を毎日使う練習をしています。`,
      category: formData.category,
      isMastered: false,
    };

    setCards((prev) => [newCardItem, ...prev]);
    setIsModalOpen(false);
    setSelectedCategory('all');
    setStatusFilter('all');
    setCurrentIndex(0);
    setIsFlipped(false);
    setFormData(initialFormState);
  };

  return (
    <div className="app-container">
      {/* アプリヘッダー */}
      <header className="app-header">
        <h1 className="header-title">
          <Sparkles size={28} />
          英単語3Dフラッシュカード
        </h1>
        <p className="header-subtitle">
          立体的なカード反転と音声発音で楽しくスピーディーに語彙力を定着
        </p>
      </header>

      {/* 統計バー & 進捗状況 */}
      <section>
        <div className="stats-bar">
          <div className="stat-item">
            <span className="stat-value">{totalCount}</span>
            <span className="stat-label">総単語数</span>
          </div>
          <div className="stat-item">
            <span className="stat-value stat-value-mastered">
              {masteredCount}
            </span>
            <span className="stat-label">習得済み</span>
          </div>
          <div className="stat-item">
            <span className="stat-value stat-value-learning">
              {learningCount}
            </span>
            <span className="stat-label">学習中</span>
          </div>
          <div className="stat-item">
            <span className="stat-value stat-value-total">
              {masterPercentage}%
            </span>
            <span className="stat-label">達成率</span>
          </div>
        </div>

        <div className="progress-container">
          <div className="progress-bar">
            <div
              className="progress-fill"
              style={{ width: `${masterPercentage}%` }}
              role="progressbar"
              aria-valuenow={masterPercentage}
              aria-valuemin={0}
              aria-valuemax={100}
            />
          </div>
        </div>
      </section>

      {/* フィルターセクション */}
      <section className="filter-section">
        <div className="category-tabs">
          <button
            type="button"
            className={selectedCategory === 'all' ? 'tab-btn tab-btn-active' : 'tab-btn'}
            onClick={() => setSelectedCategory('all')}
          >
            すべて
          </button>
          {CATEGORY_OPTIONS.map((opt) => (
            <button
              key={opt.id}
              type="button"
              className={selectedCategory === opt.id ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setSelectedCategory(opt.id)}
            >
              {opt.label}
            </button>
          ))}
        </div>

        <div className="status-filters">
          <button
            type="button"
            className={statusFilter === 'all' ? 'status-btn status-btn-active' : 'status-btn'}
            onClick={() => setStatusFilter('all')}
          >
            全ステータス
          </button>
          <button
            type="button"
            className={statusFilter === 'learning' ? 'status-btn status-btn-active' : 'status-btn'}
            onClick={() => setStatusFilter('learning')}
          >
            学習中のみ
          </button>
          <button
            type="button"
            className={statusFilter === 'mastered' ? 'status-btn status-btn-active' : 'status-btn'}
            onClick={() => setStatusFilter('mastered')}
          >
            習得済みのみ
          </button>
        </div>
      </section>

      {/* カード表示領域 */}
      <main>
        {filteredCards.length > 0 && currentCard ? (
          <>
            <FlashCardItem
              card={currentCard}
              isFlipped={isFlipped}
              onFlip={handleFlip}
              currentIndex={currentIndex}
              totalCards={filteredCards.length}
            />

            <CardControls
              onPrev={handlePrev}
              onNext={handleNext}
              onMarkMastered={handleMarkMastered}
              onMarkLearning={handleMarkLearning}
              onShuffle={handleShuffle}
              onOpenAddModal={() => setIsModalOpen(true)}
              canPrev={currentIndex > 0}
              canNext={currentIndex < filteredCards.length - 1}
              isMastered={currentCard.isMastered}
            />
          </>
        ) : (
          <div className="empty-state">
            <AlertCircle size={40} color="#94a3b8" />
            <p>条件に一致する英単語カードが見つかりません。</p>
            <div style={{ display: 'flex', gap: '8px' }}>
              <button type="button" className="btn-reset" onClick={handleResetFilters}>
                <RefreshCw size={14} style={{ display: 'inline', marginRight: '4px' }} />
                フィルターを解除
              </button>
              <button
                type="button"
                className="add-card-toggle"
                onClick={() => setIsModalOpen(true)}
              >
                <Plus size={14} style={{ display: 'inline', marginRight: '4px' }} />
                この条件で単語を追加
              </button>
            </div>
          </div>
        )}
      </main>

      {/* 単語追加モーダル */}
      {isModalOpen && (
        <div
          className="modal-backdrop"
          onClick={() => setIsModalOpen(false)}
          role="dialog"
          aria-modal="true"
        >
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h2 className="modal-title">
              <BookOpen size={22} color="#4f46e5" />
              新しい単語カードを追加
            </h2>
            <form onSubmit={handleAddCardSubmit}>
              <div className="form-group">
                <label htmlFor="card-word-input">英単語 *</label>
                <input
                  id="card-word-input"
                  name="word"
                  type="text"
                  className="form-input"
                  placeholder="例: persistent"
                  value={formData.word}
                  onChange={handleFormChange}
                  required
                  autoFocus
                />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                <div className="form-group">
                  <label htmlFor="card-phonetic-input">発音記号</label>
                  <input
                    id="card-phonetic-input"
                    name="phonetic"
                    type="text"
                    className="form-input"
                    placeholder="例: /pəˈsɪs.tənt/"
                    value={formData.phonetic}
                    onChange={handleFormChange}
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="card-part-select">品詞</label>
                  <select
                    id="card-part-select"
                    name="partOfSpeech"
                    className="form-input"
                    value={formData.partOfSpeech}
                    onChange={handleFormChange}
                  >
                    <option value="名詞">名詞</option>
                    <option value="動詞">動詞</option>
                    <option value="形容詞">形容詞</option>
                    <option value="副詞">副詞</option>
                    <option value="前置詞・熟語">前置詞・熟語</option>
                  </select>
                </div>
              </div>

              <div className="form-group">
                <label htmlFor="card-meaning-input">日本語の意味 *</label>
                <input
                  id="card-meaning-input"
                  name="meaning"
                  type="text"
                  className="form-input"
                  placeholder="例: 粘り強い、持続する"
                  value={formData.meaning}
                  onChange={handleFormChange}
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="card-category-select">カテゴリー</label>
                <select
                  id="card-category-select"
                  name="category"
                  className="form-input"
                  value={formData.category}
                  onChange={handleFormChange}
                >
                  {CATEGORY_OPTIONS.map((opt) => (
                    <option key={opt.id} value={opt.id}>
                      {opt.label} ({opt.id})
                    </option>
                  ))}
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="card-example-en">英語例文</label>
                <textarea
                  id="card-example-en"
                  name="exampleEn"
                  className="form-textarea"
                  placeholder="例: He was persistent in pursuing his goals."
                  value={formData.exampleEn}
                  onChange={handleFormChange}
                />
              </div>

              <div className="form-group">
                <label htmlFor="card-example-ja">例文の日本語訳</label>
                <textarea
                  id="card-example-ja"
                  name="exampleJa"
                  className="form-textarea"
                  placeholder="例: 彼は目標の追求において粘り強かった。"
                  value={formData.exampleJa}
                  onChange={handleFormChange}
                />
              </div>

              <div className="form-actions">
                <button
                  type="button"
                  className="btn-cancel"
                  onClick={() => setIsModalOpen(false)}
                >
                  キャンセル
                </button>
                <button type="submit" className="btn-submit">
                  カードを追加
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
